from qiskit_addon_opt_mapper import OptimizationProblem
from qiskit_addon_opt_mapper.converters import OptimizationProblemToHubo

linear = {'x0': 0, 'x1': 3, 'x2': 2, 'x3': 2}
quadratic = {('x0', 'x1'): 3, ('x2', 'x3'): 1}
cubic = {('x0', 'x1', 'x2'): -1, ('x1', 'x2', 'x3'): 3}

# Define the problem. The objective is constructed using the linear and quadratic 
# coefficients, with higher order terms passed via the higher_order dictionary.
problem = OptimizationProblem(
    objective={
        'linear': linear,
        'quadratic': quadratic,
        'higher_order': {3: cubic}
    },
    minimize=True
)

# Convert the higher-order problem to a HUBO (Higher-order Unconstrained Binary Optimization)
# and then map it to an Ising Hamiltonian.
converter = OptimizationProblemToHubo()
hubo = converter.convert(problem)
problem_hamiltonian, energy_offset = hubo.to_ising()

from qiskit_addon_opt_mapper import OptimizationProblem
from qiskit_addon_opt_mapper.converters import OptimizationProblemToHubo

linear = {'x0': 0, 'x1': 3, 'x2': 2, 'x3': 2}
quadratic = {('x0', 'x1'): 3, ('x2', 'x3'): 1}
cubic = {('x0', 'x1', 'x2'): -1, ('x1', 'x2', 'x3'): 3}

# Define the variables
vars = ['x0', 'x1', 'x2', 'x3']

# The OptimizationProblem constructor expects objective as a dict for linear, 
