problem = OptimizationProblem(
    objective={
        'linear': linear,
        'quadratic': quadratic,
        'higher_order': {3: cubic}
    },
    bounds={v: (0, 1) for v in vars}
)

# Use OptimizationProblemToHubo to handle higher-order terms
converter = OptimizationProblemToHubo()
hubo = converter.convert(problem)

# Map the HUBO to an Ising Hamiltonian
problem_hamiltonian, energy_offset = hubo.to_ising()

from qiskit_addon_opt_mapper import OptimizationProblem
from qiskit_addon_opt_mapper.converters import OptimizationProblemToHubo

linear = {'x0': 0, 'x1': 3, 'x2': 2, 'x3': 2}
