cubic = {('x0', 'x1', 'x2'): -1, ('x1', 'x2', 'x3'): 3}

# Create the problem. 
# Note: OptimizationProblem typically takes binary_vars and objective as arguments.
# The objective is constructed from linear, quadratic, and higher_order terms.
problem = OptimizationProblem(
    binary_vars=['x0', 'x1', 'x2', 'x3'],
    objective={
        'linear': linear,
        'quadratic': quadratic,
        'higher_order': {3: cubic}
    }
)

# Use OptimizationProblemToHubo to handle the cubic terms
converter = OptimizationProblemToHubo()
hubo = converter.convert(problem)

# Map the HUBO to an Ising Hamiltonian
problem_hamiltonian, energy_offset = hubo.to_ising()
